1	"use client";
2	
3	import { useEffect, useRef, useState, useSyncExternalStore } from "react";
4	import { ArrowUp, Mic, Plus } from "lucide-react";
5	import { motion, useReducedMotion } from "framer-motion";
6	import { IMAGE_ACCEPT } from "./image";
7	
8	/**
9	 * The homepage prompt box, on the Create page.
10	 *
11	 * ## Why this is a COPY of components/marketing/PromptHero.tsx, not an import
12	 *
13	 * PromptHero is a marketing component and it carries marketing concerns that
14	 * are wrong — not merely unnecessary — on a page reached only by a signed-in
15	 * customer:
16	 *
17	 *   - it stashes the prompt in sessionStorage and pushes /signup (the auth
18	 *     wall). Here there is nothing to stash and nobody to sign up.
19	 *   - it renders a "get N free credits" rewards pill. The signed-in customer
20	 *     has a real balance, stated honestly below the box by CreditNote.
21	 *   - it probes /api/auth/me to decide whether to offer Enhance. Here the
22	 *     answer is always yes, so the probe is a round trip for nothing.
23	 *   - it links out to /wizard and offers a paperclip reference-image picker;
24	 *     this page opens the wizard IN PLACE and has no reference-image path.
25	 *
26	 * Importing it would mean adding props to another owner's file to switch all
27	 * of that off. So the parts the owner asked to keep — the glass treatment, the
28	 * two-layer rotating glow ring, and the Web Speech voice-to-text — are copied
29	 * verbatim below, comments included.
30	 *
31	 * ## The pair must stay recognisably identical
32	 *
33	 * If you change the glow geometry, the SPIN_SQUARE arithmetic, the composer's
34	 * border/shadow treatment, or the speech plumbing HERE, go and look at
35	 * components/marketing/PromptHero.tsx, and vice versa. They are two copies of
36	 * one design on purpose; they are not allowed to drift into two designs.
37	 * `.glow-clip-a/-b` and `.glow-spin-a/-b` in app/globals.css are genuinely
38	 * shared — that file explains the technique and what was tried and rejected.
39	 */
40	
41	// The rotating gradient inside each glow clip MUST be a square that is
42	// larger than the clip's diagonal, or it stops covering the clip partway
43	// through its own rotation and the ring visibly vanishes and returns on a
44	// loop. (An `inset-[-50%]` made it 2x the clip in BOTH axes — e.g.
45	// 1372x296 for a wide composer. Rotated 90deg that occupies 296x1372: only
46	// 296px wide, far short of the ~686px the clip needs covered. Hence "the
47	// glow keeps disappearing.")
48	//
49	// 200% width + aspectRatio 1 gives a square of side 2*clipWidth, which
50	// always exceeds the diagonal. Centering uses margins rather than a
51	// translate because `transform` is owned by the rotation keyframes and a
52	// transform in the animation would override any translate set here —
53	// percentage margins (all sides, per spec) resolve against the containing
54	// block's WIDTH, so -100% on both axes lands the square's center exactly
55	// on the clip's center.
56	const SPIN_SQUARE: React.CSSProperties = {
57	  position: "absolute",
58	  left: "50%",
59	  top: "50%",
60	  width: "200%",
61	  aspectRatio: "1",
62	  marginLeft: "-100%",
63	  marginTop: "-100%",
64	};
65	
66	// The Web Speech API has no types in TypeScript's DOM lib, so this is a
67	// minimal hand-written shim covering exactly the surface used below —
68	// narrower than the real spec on purpose, so it can't quietly drift into
69	// asserting support for members this component never touches.
70	type SpeechRecognitionAlternativeLike = { readonly transcript: string };
71	type SpeechRecognitionResultLike = {
72	  readonly length: number;
73	  readonly [index: number]: SpeechRecognitionAlternativeLike;
74	};
75	type SpeechRecognitionEventLike = {
76	  readonly results: {
77	    readonly length: number;
78	    readonly [index: number]: SpeechRecognitionResultLike;
79	  };
80	};
81	type SpeechRecognitionLike = {
82	  continuous: boolean;
83	  interimResults: boolean;
84	  lang: string;
85	  start: () => void;
86	  stop: () => void;
87	  onresult: ((e: SpeechRecognitionEventLike) => void) | null;
88	  onend: (() => void) | null;
89	  onerror: (() => void) | null;
90	};
91	type SpeechRecognitionCtor = new () => SpeechRecognitionLike;
92	
93	// Narrowed locally rather than via `declare global`: augmenting Window would
94	// collide with the (differently-shaped) definitions any future TS DOM lib
95	// ships for this API.
96	type SpeechCapableWindow = {
97	  SpeechRecognition?: SpeechRecognitionCtor;
98	  webkitSpeechRecognition?: SpeechRecognitionCtor;
99	};
100	
101	function getSpeechRecognition(): SpeechRecognitionCtor | null {
102	  if (typeof window === "undefined") return null;
103	  const w = window as unknown as SpeechCapableWindow;
104	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
105	}
106	
107	// Feature detection is *external* state: it is unknowable while rendering on
108	// the server, and rendering the mic button in the server HTML would be a
109	// hydration mismatch. useSyncExternalStore is the sanctioned way to express
110	// that — getServerSnapshot() feeds both SSR and the hydration render, and
111	// React re-reads getSnapshot() only once hydration has finished. Support
112	// never changes within a page's life, so subscribe is a no-op.
113	const NEVER_CHANGES = () => () => {};
114	const readSpeechSupported = () => getSpeechRecognition() !== null;
115	const speechUnsupportedOnServer = () => false;
116	
117	export function PromptBox({
118	  value,
119	  onChange,
120	  onSubmit,
121	  canSubmit,
122	  onAttachFile,
123	  children,
124	}: {
125	  value: string;
126	  onChange: (next: string) => void;
127	  onSubmit: () => void;
128	  /** False while the box is empty, or while a build would be refused outright. */
129	  canSubmit: boolean;
130	  /**
131	   * A file arrived via the "+" picker, a paste, or a drop onto the box.
132	   * `extraIgnored` is the count of additional files dropped alongside it that
133	   * were never looked at — the pipeline only ever attaches one, so the
134	   * caller can tell the customer the rest were ignored rather than silently
135	   * dropping them with no explanation. PromptBox does no validation of its
136	   * own (file type, size, re-encoding): that all lives with the state this
137	   * feeds, same as it already did for the wizard/template hand-off.
138	   */
139	  onAttachFile: (file: File, extraIgnored?: number) => void;
140	  /** Rendered inside the box, above the textarea — the template badge and the
141	      attached-image row. Inside rather than above so the glow still hugs the
142	      one box the customer is looking at. */
143	  children?: React.ReactNode;
144	}) {
145	  const reduced = useReducedMotion();
146	  const [focused, setFocused] = useState(false);
147	  const [listening, setListening] = useState(false);
148	  const [dragOver, setDragOver] = useState(false);
149	  const dragDepth = useRef(0);
150	  const fileInputRef = useRef<HTMLInputElement>(null);
151	  const speechSupported = useSyncExternalStore(
152	    NEVER_CHANGES,
153	    readSpeechSupported,
154	    speechUnsupportedOnServer,
155	  );
156	  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
157	  const baseValueRef = useRef("");
158	
159	  function toggleListening() {
160	    const Ctor = getSpeechRecognition();
161	    if (!Ctor) return;
162	
163	    if (listening) {
164	      recognitionRef.current?.stop();
165	      return;
166	    }
167	
168	    const rec = new Ctor();
169	    rec.continuous = true;
170	    rec.interimResults = true;
171	    rec.lang = "en-US";
172	    baseValueRef.current = value ? value.trim() + " " : "";
173	
174	    rec.onresult = (e: SpeechRecognitionEventLike) => {
175	      let transcript = "";
176	      for (let i = 0; i < e.results.length; i++) transcript += e.results[i][0].transcript;
177	      onChange((baseValueRef.current + transcript).trimStart());
178	    };
179	    rec.onend = () => setListening(false);
180	    rec.onerror = () => setListening(false);
181	
182	    recognitionRef.current = rec;
183	    rec.start();
184	    setListening(true);
185	  }
186	
187	  useEffect(() => () => recognitionRef.current?.stop(), []);
188	
189	  // Counted rather than a plain boolean: dragging over a CHILD element (the
190	  // textarea, the badge row) fires dragleave on the parent before dragenter
191	  // on the child lands, and a boolean flips the drop-target state off for one
192	  // frame every time the pointer crosses an inner boundary — a visible
193	  // flicker for the whole time the pointer is over the box. The counter only
194	  // reaches zero once the pointer has actually left every nested element.
195	  function handleDragEnter(e: React.DragEvent) {
196	    e.preventDefault();
197	    dragDepth.current += 1;
198	    setDragOver(true);
199	  }
200	  function handleDragOver(e: React.DragEvent) {
201	    // Required even though it does nothing else: a dragover with no handler
202	    // (or one that doesn't preventDefault) tells the browser this element is
203	    // not a valid drop target, and the drop event never fires at all.
204	    e.preventDefault();
205	  }
206	  function handleDragLeave(e: React.DragEvent) {
207	    e.preventDefault();
208	    dragDepth.current = Math.max(0, dragDepth.current - 1);
209	    if (dragDepth.current === 0) setDragOver(false);
210	  }
211	  function handleDrop(e: React.DragEvent) {
212	    e.preventDefault();
213	    dragDepth.current = 0;
214	    setDragOver(false);
215	    const files = Array.from(e.dataTransfer.files);
216	    if (files.length > 0) onAttachFile(files[0], files.length - 1);
217	  }
218	
219	  function handlePaste(e: React.ClipboardEvent<HTMLTextAreaElement>) {
220	    const item = Array.from(e.clipboardData.items).find(
221	      (it) => it.kind === "file" && it.type.startsWith("image/"),
222	    );
223	    if (!item) return; // no image on the clipboard — let normal text paste happen
224	    const file = item.getAsFile();
225	    if (!file) return;
226	    // Stops the browser from ALSO inserting a filename or a broken inline
227	    // image placeholder into the textarea alongside the real attachment.
228	    e.preventDefault();
229	    onAttachFile(file);
230	  }
231	
232	  function handlePicked(e: React.ChangeEvent<HTMLInputElement>) {
233	    const file = e.target.files?.[0];
234	    // Cleared unconditionally so picking the SAME file twice in a row still
235	    // fires this handler the second time — the browser only emits `change`
236	    // on a value transition, and an unchanged `value` would silently no-op.
237	    e.target.value = "";
238	    if (file) onAttachFile(file);
239	  }
240	
241	  return (
242	    // This wrapper is sized to exactly the composer box — the glow layers
243	    // below position with -inset-N relative to IT, so the glow hugs just the
244	    // box and never the heading or the chips around it.
245	    <div className="relative">
246	      {/* The glow — a Gemini-style "chasing light" ring, built with only plain
247	          `transform: rotate()` + `overflow: hidden` clipping: no @property, no
248	          CSS masking (both dropped after they didn't visibly work even in a
249	          fresh, verified non-cached browser). Two layers: a thin bright one
250	          and a soft blurred halo.
251	
252	          The blur lives on the CLIP element, not on the rotating child. That
253	          ordering matters: filters apply AFTER the element (and its
254	          overflow:hidden clipping) is rendered, so the blur softens the clip's
255	          hard outer cutoff and lets the light bleed beyond the clip's bounds —
256	          a real falloff. With the blur on the child instead, the clip's crisp
257	          edge survives and the result reads as a chunky solid border.
258	
259	          Opacity is fixed, not keyed off `focused` — an earlier version dimmed
260	          on blur, which read as "disappearing". The composer's own border
261	          below is the right place for a focus affordance; this ring stays
262	          constant. The entrance fade and the ambient pulse are the
263	          glow-fade-in and glow-pulse keyframes on the outer clipper, so the
264	          global prefers-reduced-motion rule in globals.css already covers
265	          them — nothing here animates outside CSS.
266	
267	          NO NEGATIVE Z-INDEX HERE. `-z-10` drops these layers behind the
268	          nearest opaque background and they are then invisible forever. The
269	          layers sit at the default level and the composer is lifted above them
270	          with z-10, which needs no stacking-context trickery to hold. */}
271	      <div
272	        aria-hidden
273	        className="glow-clip-a pointer-events-none absolute -inset-[3px] overflow-hidden rounded-[1.9rem] blur-[5px]"
274	      >
275	        <div
276	          className="glow-spin-a"
277	          style={{
278	            ...SPIN_SQUARE,
279	            // Stops are pushed into distinct quadrants so the colour visibly
280	            // travels around the box as this rotates — closely-spaced hues
281	            // just blur into one flat pink.
282	            background:
283	              "conic-gradient(#f72570 0deg, #a33dff 90deg, #ff9868 180deg, #ff6b67 270deg, #f72570 360deg)",
284	          }}
285	        />
286	      </div>
287	      <div
288	        aria-hidden
289	        className="glow-clip-b pointer-events-none absolute -inset-[14px] overflow-hidden rounded-[2.4rem] blur-[22px]"
290	      >
291	        <div
292	          className="glow-spin-b"
293	          style={{
294	            ...SPIN_SQUARE,
295	            background:
296	              "conic-gradient(from 180deg, #a33dff 0deg, #f72570 90deg, #ff9868 180deg, #ff6b67 270deg, #a33dff 360deg)",
297	          }}
298	        />
299	      </div>
300	
301	      {/* The glass composer. Opaque enough that the animated ring behind it
302	          reads as a halo around the box, not a wash bleeding through onto the
303	          text — earlier versions were translucent enough that the strong glow
304	          showed straight through onto the placeholder. Still picks up a faint
305	          frosted quality from backdrop-blur, just not at the cost of
306	          legibility. */}
307	      <div
308	        onDragEnter={handleDragEnter}
309	        onDragOver={handleDragOver}
310	        onDragLeave={handleDragLeave}
311	        onDrop={handleDrop}
312	        className="relative z-10 overflow-hidden rounded-[1.75rem] bg-white/95 backdrop-blur-2xl backdrop-saturate-150 transition-colors duration-300 dark:bg-neutral-950/95"
313	        style={{
314	          // No focus-driven glow here — the animated ring behind the box is the
315	          // only glow, and a second one on focus fought with it. Focus is still
316	          // signalled (it must be, for keyboard users) but with a quiet border
317	          // shift, plus the textarea's own inside outline below. Dragging a
318	          // file over the box outranks both: it is the clearest sign of the
319	          // three that something is about to happen.
320	          border: `1.5px solid ${
321	            dragOver
322	              ? "var(--brand)"
323	              : focused
324	                ? "color-mix(in srgb, white 45%, var(--accent) 55%)"
325	                : "color-mix(in srgb, white 75%, var(--accent) 25%)"
326	          }`,
327	          boxShadow: "var(--sh-s), inset 0 1px 0 rgba(255,255,255,0.5)",
328	        }}
329	      >
330	        {children}
331	
332	        {/* The visible drop-target state the drag-and-drop requirement asks
333	            for. Sits above everything else in the box but never intercepts
334	            the drop itself — the box element it's layered over already owns
335	            the drag handlers, and a pointer-events-none child never steals
336	            dragenter/dragleave from its parent. */}
337	        {dragOver && (
338	          <div
339	            aria-hidden
340	            className="pointer-events-none absolute inset-0 z-20 flex items-center justify-center rounded-[1.75rem] bg-brand-tint/90 backdrop-blur-sm"
341	          >
342	            <p className="k-label text-brand-ink">Drop image to attach</p>
343	          </div>
344	        )}
345	
346	        {/* The placeholder was the only label, and it disappears on the first
347	            keystroke. A visible one would change the design, so this is a
348	            sr-only label tied to the field by id. */}
349	        <label htmlFor="create-prompt-input" className="sr-only">
350	          Describe the website you want to create
351	        </label>
352	        <textarea
353	          id="create-prompt-input"
354	          value={value}
355	          onChange={(e) => onChange(e.target.value)}
356	          onFocus={() => setFocused(true)}
357	          onBlur={() => setFocused(false)}
358	          onPaste={handlePaste}
359	          onKeyDown={(e) => {
360	            // Cmd/Ctrl+Enter builds; plain Enter makes a newline. The homepage
361	            // box sends on plain Enter because what it sends is a one-liner and
362	            // costs nothing. Here Enter starts a build that spends the
363	            // customer's credits, and a brief worth building is several
364	            // paragraphs — so this keeps the portal composer's existing rule
365	            // rather than the marketing one. It is the one deliberate
366	            // behavioural difference between the two boxes.
367	            if (e.key === "Enter" && (e.metaKey || e.ctrlKey) && canSubmit) {
368	              e.preventDefault();
369	              onSubmit();
370	            }
371	          }}
372	          rows={6}
373	          placeholder={
374	            listening ? "Listening…" : "Describe the website you want to create…"
375	          }
376	          // A focus-visible outline is drawn INSIDE (negative offset) because
377	          // the composer clips overflow, so `k-focus`'s outward ring would be
378	          // cut off. Same 2px width and the same brand ring variable, so the
379	          // product still has one focus appearance. Mouse clicks are
380	          // unaffected: focus-visible, not focus.
381	          className="w-full resize-none rounded-[1.6rem] bg-transparent px-6 pb-14 pt-5 text-[15px] leading-relaxed text-neutral-900 outline-none placeholder:text-neutral-500 focus-visible:outline-2 focus-visible:outline-offset-[-3px] focus-visible:outline-[var(--brand-ring)] dark:text-white dark:placeholder:text-neutral-400"
382	        />
383	
384	        <div className="absolute bottom-3 left-3 flex items-center gap-1">
385	          {/* The "+" IS the attach affordance for this page — there is no
386	              second, separately-labelled "attach reference image" button
387	              alongside it. Hidden input + a real button wrapping it, rather
388	              than a bare <input type="file">, because a file input cannot be
389	              styled to match the rest of this hand-rolled control row. */}
390	          <input
391	            ref={fileInputRef}
392	            type="file"
393	            accept={IMAGE_ACCEPT}
394	            tabIndex={-1}
395	            aria-hidden
396	            className="sr-only"
397	            onChange={handlePicked}
398	          />
399	          <button
400	            type="button"
401	            onClick={() => fileInputRef.current?.click()}
402	            aria-label="Attach an image"
403	            className="k-focus flex h-9 w-9 items-center justify-center rounded-full text-neutral-500 transition-colors hover:bg-black/5 hover:text-neutral-900 dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
404	          >
405	            <Plus size={16} strokeWidth={2} />
406	          </button>
407	
408	          {/* Rendered only once the client has confirmed the Web Speech API
409	              exists — see the useSyncExternalStore note above. Absent (not
410	              disabled) everywhere it would not work, which is the honest
411	              treatment for a capability the browser simply does not have. */}
412	          {speechSupported && (
413	            <button
414	              type="button"
415	              onClick={toggleListening}
416	              aria-label={listening ? "Stop voice input" : "Start voice input"}
417	              className={`k-focus relative flex h-9 w-9 items-center justify-center rounded-full transition-colors ${
418	                listening
419	                  ? "text-white"
420	                  : "text-neutral-500 hover:bg-black/5 hover:text-neutral-900 dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
421	              }`}
422	              style={listening ? { background: "var(--brand-gradient)" } : undefined}
423	            >
424	              {/* Skipped under reduced motion — it's a framer-motion (JS)
425	                  animation, so the CSS-only reduced-motion rule in globals.css
426	                  doesn't reach it. The button's solid gradient fill still shows
427	                  that recording is on. */}
428	              {listening && !reduced && (
429	                <motion.span
430	                  aria-hidden
431	                  className="absolute inset-0 rounded-full"
432	                  style={{ background: "var(--brand-gradient)" }}
433	                  animate={{ opacity: [0.5, 0, 0.5], scale: [1, 1.6, 1] }}
434	                  transition={{ duration: 1.4, repeat: Infinity, ease: "easeInOut" }}
435	                />
436	              )}
437	              <Mic size={16} strokeWidth={2} className="relative" />
438	            </button>
439	          )}
440	        </div>
441	
442	        {/* The one brand-gradient fill on this view — the primary action. */}
443	        <motion.button
444	          type="button"
445	          onClick={onSubmit}
446	          disabled={!canSubmit}
447	          aria-label="Build my site"
448	          whileHover={canSubmit ? { scale: 1.06 } : undefined}
449	          whileTap={canSubmit ? { scale: 0.94 } : undefined}
450	          className="k-focus absolute bottom-3 right-3 flex h-9 w-9 items-center justify-center rounded-full text-white shadow-[0_6px_18px_-4px_var(--glow)] transition-opacity disabled:opacity-30"
451	          style={{ background: "var(--brand-gradient)" }}
452	        >
453	          <ArrowUp size={16} strokeWidth={2.5} />
454	        </motion.button>
455	      </div>
456	    </div>
457	  );
458	}
