76	/** Base64 payload size, minus the `data:image/png;base64,` prefix. */
77	function dataUrlBytes(dataUrl: string): number {
78	  const comma = dataUrl.indexOf(",");
79	  return comma === -1 ? 0 : Math.round((dataUrl.length - comma - 1) * 0.75);
80	}
